# Price tiers in the domestic API are expressed in purchasing units; multiply by theRatio.
def commercial(c,n):
 r=p[c];d=r.get('domestic',{});price=r.get('pricing')or{};ratio=price.get('theRatio')or d.get('theRatio')or 1;minimum=d.get('minBuyNumber')
 tiers=[(x['startPurchasedNumber']*ratio,x['productPrice'])for x in price.get('productPriceList',[])]
 def cost(boards,spares):
  if minimum is None or not tiers:return '', '', ''
  qty=math.ceil(max(n*boards+spares,minimum*ratio)/ratio)*ratio
  unit=next((a for k,a in reversed(tiers)if qty>=k),None)
  return qty,unit,round(qty*unit,4)if unit is not None else ''
 record={'C号':c,'MPN':d.get('productModel',''),'品牌':d.get('productGradePlateName',''),'封装':d.get('encapsulationModel',''),'国内标签':d.get('smtLabel',''),'免换料费证据':'国内productRecord.smtLabel=SMT基础库；订单时重核'if d.get('smtLabel')=='SMT基础库'else'未取得本次国内明确免费证据；不能仅据扩展标签否定合作免费','商城库存':d.get('retail_stock')if d.get('retail_stock')is not None else '未知','SMT库存':d.get('smt_stock')if d.get('smt_stock')is not None else '未知','查询时间':r['queried_at'],'MOQ只':minimum*ratio if minimum is not None else '', '购买倍数只':ratio,'人民币阶梯只价':';'.join(f'{k}+:{a}'for k,a in tiers),'SMT只价CNY':'','SMT_MOQ':'','SMT损耗':'','采购页':r.get('url',''),'原厂资料':r.get('metadata',{}).get('pdfUrl',''),'商城1板可购':isinstance(d.get('retail_stock'),(int,float))and d['retail_stock']>=(cost(1,2)[0]or n+2),'SMT1板数量满足':isinstance(d.get('smt_stock'),(int,float))and d['smt_stock']>=n+2}
 for b,sp in [(1,0),(1,2),(5,0),(5,2)]:
  qty,unit,fee=cost(b,sp);record.update({f'{b}板+{sp}备品_商城购买量':qty,f'{b}板+{sp}备品_单价CNY':unit,f'{b}板+{sp}备品_付款CNY':fee})
 return record
allrows=[];summary=[]
for r in original:
 e=r['例外编号'];status,codes,req,why,rec=A[e];n=int(r['每板数量']);entries=[]
 for c in [r['原C号']]+codes:
  row={'例外编号':e,'角色':'当前'if c==r['原C号']else'候选/排查','当前位号':r['位号'],'当前每板数量':n,'费用假设候选每板数量':n,'结论':status,'实际电路要求':req,'判断与证据缺口':why,'推荐':rec,**commercial(c,n)}
  # Composite substitutions are priced separately with actual per-board physical counts.
  factor={('E03','C28323'):3,('E03','C28233'):3,('E14','C14858'):10,('E18','C28233'):2}.get((e,c),1)
  if factor!=1:row.update(commercial(c,n*factor));row['费用假设候选每板数量']=n*factor
  if e=='E04'and c=='C96123':row.update(commercial(c,n*2));row['费用假设候选每板数量']=n*2
  if e=='E05'and c=='C29823':row['费用口径说明']='按9只都换估算；六低压/三高压审核独立，不表示整组批准'
  elif factor!=1:row['费用口径说明']='组合路径的一项；新MPN各加2件备品。实际总订单需合并同C号，不累加重复MOQ'
  else:row['费用口径说明']='独立型号组商城采购估算；候选/排查不表示批准；不是SMT单价或实际订单'
  allrows.append(row);entries.append(row)
 nets='；'.join(ref+':'+','.join(str(v)if v is not None else 'NC'for v in parts[ref]['pins'].values())for ref in r['位号'].split(','))
 summary.append({'例外编号':e,'位号':r['位号'],'当前MPN':r['原MPN'],'当前C号':r['原C号'],'每板数量':n,'结论':status,'候选C号':codes,'实际电路要求':req,'电路节点':nets,'判断与证据缺口':why,'推荐':rec})
fields=list(allrows[0]);fields+=['费用口径说明']if '费用口径说明'not in fields else[]
